args.command:
cat > /tmp/fuzz_categorize.sh <<'EOF'
#!/bin/bash
CPP=/workspace/dataset/test11_executable
RUST=/output/test11
a=0; b=0; c=0; d=0; ok=0; total=0
declare -a catB catC
run_case() {
  total=$((total+1))
  local out_cpp out_rust rc_cpp rc_rust
  out_cpp=$("$CPP" "$@" 2>/dev/null); rc_cpp=$?
  out_rust=$("$RUST" "$@" 2>/dev/null); rc_rust=$?
  if [ "$out_cpp" = "$out_rust" ]; then
    if [ $rc_cpp -eq $rc_rust ] || { [ $rc_cpp -ne 0 ] && [ $rc_rust -ne 0 ]; }; then
      ok=$((ok+1)); return
    fi
  fi
  if [ $rc_cpp -eq 134 ] && [ $rc_rust -eq 0 ]; then a=$((a+1));
  elif [ $rc_cpp -eq 0 ] && [ $rc_rust -eq 101 ]; then b=$((b+1)); catB+=("[$*]")
  elif [ $rc_cpp -eq 0 ] && [ $rc_rust -eq 0 ]; then c=$((c+1)); catC+=("[$*]")
  else d=$((d+1)); echo "OTHER: [$*] cpp_rc=$rc_cpp rust_rc=$rc_rust"; fi
}
run_case
while IFS=$'\t' read -r x y z; do run_case "$x" "$y" "$z"; done < <(perl -e '
srand(20260809);
for (1..600) {
  my @t;
  for (1..3) {
    my $r = rand(); my ($e,$m);
    if ($r < 0.15) { $e = -46 + int(rand(8)); }
    elsif ($r < 0.30) { $e = -38 + int(rand(10)); }
    else { $e = int(rand(77)) - 38; }
    $m = rand(9.999999) + 0.000001;
    my $s = rand() < 0.5 ? "-" : "";
    push @t, sprintf("%s%.10ge%d", $s, $m, $e);
  }
  print join("\t", @t), "\n";
}
print "1e-40\t5e-39\t1.4e-45\n-1e-40\t-5e-39\t-1e-45\n1e-45\t2e-45\t4e-45\n";
')
run_case 3.4028235e38 -3.4028235e38 1e38
run_case 3.4028236e38 0 0
run_case -3.4028235e38 -3.4028235e38 -3.4028235e38
run_case 1e38 1e-38 -1e38
run_case 1e2 .5 5.
run_case "  0.5" "  1" "   2"
run_case 0x1p-1 0x1.8p1 1
run_case inf -inf 0.5
run_case nan 0.5 0.5
run_case INF NAN infinity
run_case 1e100 0 0
run_case -1e100 1 2
run_case 1e-100 0 0
run_case 5x 0.5 0.5
run_case abc 1 2
run_case 1,5 2 3
run_case +1.5 +.25 +3e0
run_case 0 -0 0.0
run_case 1_000 2 3
run_case "1e" 2 3
echo "==== TOTAL=$total OK=$ok"
echo "CAT-A cpp aborts (stof out_of_range), rust succeeds: $a"
echo "CAT-B cpp ok, rust parse-fails: $b"; printf '  %s\n' "${catB[@]}"
echo "CAT-C both rc=0, stdout differs: $c"; printf '  %s\n' "${catC[@]}"
echo "CAT-D other: $d"
EOF
chmod +x /tmp/fuzz_categorize.sh && /tmp/fuzz_categorize.sh
